package com.powercms.cms.widget;
import com.fasterxml.jackson.databind.ObjectMapper; import com.powercms.cms.audit.AuditService; import com.powercms.cms.widget.entity.*; import com.powercms.cms.widget.repo.*; import com.powercms.common.error.BusinessException; import org.junit.jupiter.api.*; import java.util.*; import static org.junit.jupiter.api.Assertions.*; import static org.mockito.ArgumentMatchers.*; import static org.mockito.Mockito.*;
class WidgetServiceTest { WidgetDefinitionRepository repo=mock(WidgetDefinitionRepository.class); AuditService audit=mock(AuditService.class); WidgetService service=new WidgetService(repo,new ObjectMapper(),audit); UUID site=UUID.randomUUID(); @Test void validatesDslAndPublishesOnlySameSite(){when(repo.save(any())).thenAnswer(i->{var w=i.getArgument(0,WidgetDefinitionEntity.class);return w;});var info=service.save(site,null,"news","News","{\"route\":\"/news\",\"view\":\"/templates/news.ftl\"}","{\"type\":\"object\",\"properties\":{}}","a");assertEquals("DRAFT",info.status());var w=new WidgetDefinitionEntity();w.setSiteId(site);when(repo.findById(any())).thenReturn(Optional.of(w));assertEquals("PUBLISHED",service.publish(site,UUID.randomUUID(),"a").status());} @Test void rejectsNonDslAndCrossSite(){assertThrows(BusinessException.class,()->service.save(site,null,"x","x","Groovy","{\"properties\":{}}","a"));var w=new WidgetDefinitionEntity();w.setSiteId(UUID.randomUUID());when(repo.findById(any())).thenReturn(Optional.of(w));assertThrows(BusinessException.class,()->service.publish(site,UUID.randomUUID(),"a"));}}
